  const as64 = BigInt.asUintN(64, value);

  // Extract low 32 bits and high 32 bits as unsigned integers.
  const lowBits = BigInt.asUintN(32, as64);
  const highBits = (as64 - lowBits) >> BigInt(32);

  split64Low = Number(lowBits);
  split64High = Number(highBits);
