  // Must ensure the values are handled as unsigned, any bitwise operations
  // on the input arguments would have turned them into signed values (e.g.
  // zigzag decoding).
  bitsHigh = bitsHigh >>> 0;
  bitsLow = bitsLow >>> 0;
