goog.loadModule(function(exports) {'use strict';/**
 * @fileoverview Chrome port of GoogleTTS.
 */

'use strict';

goog.module('GoogleTtsEngine');

const Annotation = goog.require('proto.speech.tts.lucid.Annotation');
const Content = goog.require('proto.speech.tts.lucid.LucidMarkup.Content');
const LucidMarkup = goog.require('proto.speech.tts.lucid.LucidMarkup');
const LucidPiece = goog.require('proto.speech.tts.lucid.LucidPiece');
const LucidUtterance = goog.require('proto.speech.tts.lucid.LucidUtterance');
const Prosody = goog.require('proto.speech.tts.lucid.Prosody');
const SHA256 = goog.require('SHA256');
const SpeakerParams = goog.require('proto.speech.tts.SpeakerParams');
const Text = goog.require('proto.speech.tts.Text');
const {LanguagePacksConnection} = goog.require('LanguagePacksConnection');
const {TtsEventObserver} = goog.require('TtsEventObserver');
const {TtsStream} = goog.require('TtsStream');

/**
 * @typedef {{
 *  gender: string,
 *  name: string,
 *  speaker: string,
 * }}
 */
let SpeakerData;


/**
 * Stores all relevant data for a voice.
 * @typedef {{
*  compressed_size: number,
*  displayName: string,
*  file_id: string,
*  id: string,
*  language: string,
*  remote: boolean,
*  sha256_checksum: string,
*  speakers: !Array<!SpeakerData>,
*  unloaded: boolean,
*  url: string,
* }}
*
* Example VoiceData:
* {
*  compressed_size: 12853955,
*  displayName: 'English (United States),
*  file_id: 'en-us-x-multi-r48',
*  id: 'en-us-x-multi',
*  language: 'en-US',
*  remote: false,
*  sha256_checksum: 'abcdefg',
*  speakers: [
*    {
*      gender: 'female',
*      name: 'Chrome OS US English 1',
*      speaker: 'sfg'
*    },
*  ],
*  unloaded: true,
*  url: 'https://dl.google.com/.../en-us-x-multi-r48.zvoice',
* }
*/
let VoiceData;

/**
 * @typedef {{
 *  type: string,
 *  data: (!VoiceData|undefined),
 * }}
 */
let Command;

/** @typedef {function(!chrome.tts.TtsEvent): void} */
let TtsEngineApiCallback;

/** @const {string} */
const GET_VOICE_BYTES_METRIC_NAME = 'TextToSpeech.Settings.GetVoiceBytes';

/** @enum {number} */
const GET_VOICE_BYTES_METRIC_VALUES = {
  DLC_SUCCESS: 0,
  DLC_NOT_FOUND: 1,
  DLC_NO_CONTENTS: 2,
  XHR_SUCCESS: 3,
  XHR_NO_CONTENTS: 4,
};

class GoogleTtsEngine {
  constructor() {
    /**
     * Whether or not this class is being used from a Tast test. Labeled as
     * const since it's never modified in this file and will only ever be
     * modified by Tast.
     * @private {boolean}
     * @const
     */
    this.isTastTest_ = false;

    /**
     * The callback provided by a call to chrome.ttsEngine.onSpeak, which is
     * our channel to send status updates about the progress of speech.
     * @private {?TtsEngineApiCallback}
     */
    this.ttsEngineApiCallback_ = null;

    /**
     * The string containing the text we're currently speaking.
     * @private {string?}
     */
    this.utterance_ = null;

    /**
     * The current voice's name.
     * Example: 'Chrome OS US English 1'.
     * @private {string?}
     */
    this.currentVoice_ = null;

    /**
     * Callback to run after initialization.
     * @private
     */
    this.pendingCallback_ = null;

    /**
     * True if initialization is done.
     * @private {boolean}
     */
    this.initialized_ = false;

    /** @private {?IDBDatabase} */
    this.db_ = null;

    /**
     * Maps voice names to either a remote URL or local filepath to a .zvoice
     * (zipped) file. Example entries include:
     * 'Chrome OS US English 1': '/en-us-x-multi.zvoice',
     * 'Chrome OS italiano': 'https://dl.google.com/.../it-it-x-multi.zvoice'.
     * @private {!Object<string, string>}
     * @const
     */
    this.voiceNameToUrl_ = {};

    /**
     * Maps voice names to their IDs. These are typically file names without
     * the '.zvoice' part. Example entries include:
     * 'Chrome OS US English 1': 'en-us-x-multi',
     * 'Chrome OS italiano 1': 'it-it-x-multi'
     * @private {!Object<string, string>}
     * @const
     */
    this.voiceNameToId_ = {};

    /**
     * Maps voice names to their file IDs. These are typically full file names
     * that also include a voice version number. Example entries include:
     * 'Chrome OS US English 1': 'en-us-x-multi-r48',
     * 'Chrome OS italiano 1': 'it-it-x-multi-r33'
     * @private {!Object<string, string>}
     * @const
     */
    this.voiceNameToFileId_ = {};

    /**
     * Maps voice names to their speaker names. Example entries include:
     * 'Chrome OS US English 1': 'fis',
     * 'Chrome OS US English 2': 'rjs'
     * @private {!Object<string, string>}
     * @const
     */
    this.voiceNameToSpeakerName_ = {};

    /**
     * @private {!Object<string, string>}
     * @const
     */
    this.speakerNameToGender_ = {};

    /**
     * Stores all necessary data about each voice. See typedefs for VoiceData
     * and SpeakerData for more details.
     * @private {!Array<!VoiceData>}
     */
    this.voiceData_ = [];

    /** @private {number} */
    this.volume_ = 1.0;

    /**
     * Maps a voice file id to whether it is installed locally. Example entries
     * include:
     * 'en-us-x-multi-r48': true,
     * 'it-it-x-multi-r33': false
     * @private {!Object<string, boolean>}
     * @const
     */
    this.installedVoices_ = {};

    /**
     * Represents a connection to language packs.
     * @private {?LanguagePacksConnection}
     */
    this.languagePacksConnection_ = new LanguagePacksConnection(() => {
      // If there is a connection error, then we should not use this
      // object.
      this.languagePacksConnection_ = null;
    }, () => this.updateVoices_());

    /**
     * Whether High-Quality voices are enabled.
     * @private {boolean}
     */
    this.highQualityVoicesEnabled_ = false;
    chrome.accessibilityPrivate.isFeatureEnabled(chrome.accessibilityPrivate.AccessibilityFeature.GOOGLE_TTS_HIGH_QUALITY_VOICES, (enabled) => {
      this.highQualityVoicesEnabled_ = enabled;
    });

    /** @private {?TtsStream} */
    this.ttsStream_ = new TtsStream(() => {
      // Runs if there is a connection error with `ttsStream_`.
      this.ttsStream_ = null;
    });

    this.registerListeners_();
    this.initializeIndexDB_();
  }

  /** @private */
  registerListeners_() {
    // Start listening to chrome.ttsEngine requests early so we queue up any
    // utterances and speak them as soon as we've actually initialized.
    chrome.ttsEngine.onSpeak.addListener(this.onSpeak.bind(this));
    chrome.ttsEngine.onStop.addListener(this.onStop.bind(this));
    chrome.ttsEngine.onPause.addListener(this.onPause.bind(this));
    chrome.ttsEngine.onResume.addListener(this.onResume.bind(this));

    chrome.runtime.onMessage.addListener((message) => {
      this.onMessage_(/** @type {!Command} */ (message));
    });
  }

  /** @private */
  async initializeIndexDB_() {
    const dbRequest = indexedDB.open('store', 1);

    dbRequest.onsuccess = () => {
      this.db_ = dbRequest.result;
      this.finishInitialization_();
    };

    dbRequest.onerror = () => {
      console.error(
          'Unable to initialize index db; downloaded voices will not work.');
      this.finishInitialization_();
    };

    /**
     * Runs when a version change occurs. For us, this should only ever occur
     * once.
     */
    dbRequest.onupgradeneeded = () => {
      dbRequest.result.createObjectStore('store');
    };
  }

  /** @private */
  async finishInitialization_() {
    await this.initializeVoiceData_();
    await this.updateVoices_();
    this.initialized_ = true;
    if (this.pendingCallback_) {
      this.pendingCallback_();
      this.pendingCallback_ = null;
    }
  }

  /**
   * Retrieves metadata about voices and saves it to `voiceData_`.
   * @private
   */
  async initializeVoiceData_() {
    const response = await fetch(chrome.runtime.getURL('voices.json'));
    const json = await response.json();
    this.voiceData_ = /** @type {!Array<!VoiceData>} */ (json);
    if (!this.highQualityVoicesEnabled_) {
      this.voiceData_ = this.voiceData_.filter(voice => !voice.id.includes('-seanet'));
    }
  }

  /**
   * Called by the client to stop speech.
   */
  onStop() {
    this.pendingCallback_ = null;
    if (!this.initialized_) {
      return;
    }
    this.ttsStream_.stop();
    this.ttsEngineApiCallback_ = null;
  }

  /**
   * Called by the client to pause speech.
   */
  onPause() {
    if (!this.initialized_) {
      return;
    }
    this.ttsStream_.pause();
  }

  /**
   * Called by the client to resume speech.
   */
  onResume() {
    if (!this.initialized_) {
      return;
    }
    this.ttsStream_.resume();
  }

  /**
   * Called by the client to start speech synthesis.
   *
   * @param {string} utterance The utterance to say.
   * @param {!chrome.ttsEngine.SpeakOptions} options The options affecting the
   *   speech, like language, pitch, rate, etc.
   * @param {!TtsEngineApiCallback} callback The function to receive messages
   * from the engine.
   */
  async onSpeak(utterance, options, callback) {
    this.pendingCallback_ = null;

    if (!this.initialized_) {
      // We got a call to speak before we're initialized. Enqueue this until
      // we're ready.
      this.pendingCallback_ =
          this.onSpeak.bind(this, utterance, options, callback);
      return;
    }

    this.ttsEngineApiCallback_ = callback;
    this.utterance_ = utterance;

    if (this.currentVoice_ === options.voiceName) {
      // Already initialized, nothing to do.
      this.synthesize(utterance, options, callback);
      return;
    }

    const {voiceFileId, success} =
        await this.ensureExists(options.voiceName, /* allowDownload = */ false);
    if (!success) {
      console.log('Failed to ensure voice exists.');
      return;
    }

    const pipelineSuccess = await this.loadPipeline(voiceFileId);
    if (!pipelineSuccess) {
      console.log('Failed to initialize pipeline');
      return;
    }

    this.currentVoice_ = options.voiceName || '';
    this.synthesize(utterance, options, callback);
  }

  /**
   * Synthesizes some text. Assumes everything is already set up.
   *
   * @param {string} utterance The utterance to synthesize.
   * @param {!chrome.ttsEngine.SpeakOptions} options Options such as language,
   *    pitch etc.
   * @param {!TtsEngineApiCallback} callback Gets called with TtsEvents from the
   *    engine.
   */
  synthesize(utterance, options, callback) {
    let lucid = new LucidMarkup();

    if (options.rate || options.pitch) {
      let annotation = new Annotation();
      let prosody = new Prosody();
      if (options.rate) {
        // The Chrome TTS spec disallows anything outside the
        // range of 0.1 through 10.0. Lucid Markup matches the Chrome spec where
        // > 1 is a speedup and < 1 is a slowdown.
        let durScale = Math.min(Math.max(options.rate, 0.1), 10.0);
        prosody.setSpeechRate(durScale);
      }

      // Converts the scale of 'pitch' from the API-oriented [0.0, 1.0] range
      // to pitch scale-factor range via an intrinsic (logarithmic) [-20, +20]
      // semitone scale.
      if (options.pitch) {
        const kPitchModificationRangeInSemitones = 20;
        let f0Scale = Math.pow(
            2.0,
            2.0 * (options.pitch / 2.0 - 0.5) *
                kPitchModificationRangeInSemitones / 12.0);
        prosody.setF0Scale(f0Scale);
      }

      annotation.setProsody(prosody);
      lucid.setAnnotation(annotation);
    }

    if (options.volume) {
      this.volume_ = Math.min(Math.max(options.volume, 0.0), 1.0);
    }

    if (!options.voiceName) {
      throw new Error(`Couldn't synthesize speech, voiceName is undefined`);
    }

    let piece = new LucidPiece().setInputText(utterance);
    let lucid_utterance = new LucidUtterance()
                              .setPiecesList([piece])
                              .setAttemptSentenceSplitting(true);
    let content = new Content().setUtterance(lucid_utterance);
    lucid.addContents(content);
    let text = new Text().setLucid(lucid);
    let serializedText = Array.from(new Uint8Array(text.serializeBinary()));
    let speakerName = this.voiceNameToSpeakerName_[options.voiceName];
    let speakerGender = this.speakerNameToGender_[speakerName];
    let speakerParams = new SpeakerParams();
    speakerParams.setSpeaker(speakerName);
    speakerParams.setGender(speakerGender);
    let serializedSpeakerParams =
        Array.from(new Uint8Array(speakerParams.serializeBinary()));
    this.ttsStream_.speak(serializedText, serializedSpeakerParams)
        .then(ttsEventObserver => {
          this.ttsStream_.setVolume(this.volume_);
          if (!this.ttsEngineApiCallback_ || !this.utterance_) {
            throw new Error(`Couldn't create TtsEventObserver, undefined callback or undefined utterance.`);
          }

          new TtsEventObserver(ttsEventObserver, this.ttsEngineApiCallback_, this.utterance_);
        });

    /**
     * If this is a Tast test and |testUtterances| is defined on window (both
     * of the above will be set by Tast), then add speech data for tests.
     * @suppress {strictMissingProperties}
     */
    const pushUtteranceDataForTest = this.isTastTest_ && window.testUtterances;
    if (pushUtteranceDataForTest) {
      /** @suppress {missingProperties} */
      window.testUtterances.push({utterance: utterance, options: options});
    }
  }

  /**
   * Load up a pipeline.
   * @param {string} voiceFileId
   * @return {!Promise<boolean>}
   */
  async loadPipeline(voiceFileId) {
    return this.ttsStream_.selectVoice(voiceFileId);
  }

  /**
   * Returns true if the voice is remote.
   * @param {string} voiceFileId
   * @return {boolean}
   * @private
   */
  isVoiceRemote_(voiceFileId) {
    const voice = this.voiceData_.find(voice => voice['file_id'] === voiceFileId);
    if (!voice) {
      return false;
    }
    return voice.remote;
  }

  /**
   * Makes sure that a voice is locally installed on disk that the tts library
   * uses. First, checks to see if the voice data is already on disk. Next,
   * tries to retrieve from IndexedDB. Finally, downloads from either Google
   * servers or language packs (only if requested and if all other lookups
   * fail).
   *
   * @param {string|undefined} voiceName Name of the voice to look up.
   * @param {boolean} allowDownload The caller wants to download the voice if it
   * does not exist locally.
   * @return {!Promise<{voiceFileId: string, success: boolean}>}
   */
  async ensureExists(voiceName, allowDownload) {
    if (!voiceName) {
      throw new Error('voiceName is undefined');
    }

    const voiceFileId = this.voiceNameToFileId_[voiceName];
    if (!voiceFileId) {
      throw new Error(`Invalid voice name: ${voiceName}`);
    }

    if (voiceFileId.includes('-seanet') && this.highQualityVoicesEnabled_) {
      const baseId = voiceFileId.replace('-seanet', '');
      const baseName = Object.entries(this.voiceNameToFileId_).find(([name, id]) => id === baseId)[0];
      await this.ensureExists(baseName, /* allowDownload = */ false);
    }

    // The voice is installed locally.
    if (this.installedVoices_[voiceFileId]) {
      return {voiceFileId, success: true};
    }

    // Do a lookup first for the voice in IndexedDB.
    const indexDbBuffer = await this.getVoiceData_(voiceFileId);
    if (indexDbBuffer) {
      const success = await this.ttsStream_.installVoice(voiceFileId, indexDbBuffer);
      this.installedVoices_[voiceFileId] = success;
      await this.updateVoices_();
      return {voiceFileId, success};
    }

    if (!voiceName) {
      throw new Error('voiceName is undefined');
    }

    let url = this.voiceNameToUrl_[voiceName];
    const isRemote = url.indexOf('http') == 0;
    if (!allowDownload && isRemote) {
      // Only fetch remote urls if the voice is remote and download was
      // requested.
      throw new Error('Unexpected remote url ' + url);
    }

    const buffer = await this.getZippedVoiceFileBytes_(voiceName);
    if (!buffer) {
      return {voiceFileId: '', success: false};
    }

    if (!this.validateVoiceData_(voiceFileId, buffer)) {
      console.error('Failed voice archive validation: ' + voiceFileId);
      return {voiceFileId: '', success: false};
    }

    const success = await this.ttsStream_.installVoice(voiceFileId, buffer);
    this.installedVoices_[voiceFileId] = success;

    // If the voice was downloaded from the server, save it to IndexedDB
    // for future loads.
    if (success && allowDownload) {
      this.saveVoiceData_(voiceFileId, buffer);
    }
    return {voiceFileId, success};
  }

  /**
   * @param {!Command} message
   * @private
   */
  async onMessage_(message) {
    let command = /** @type {!Command} */ (message);
    let locale = '';
    if (command.data) {
      locale = command.data.language;
    }

    switch (command.type) {
      case 'getVoices':
        this.sendToOptions_({type: 'updateVoices', data: this.voiceData_});
        break;
      case 'addVoice':
        // Use language packs if possible.
        if (this.languagePacksConnection_ && Boolean(LanguagePacksConnection.localeToDlc(locale))) {
          // All we need to do is call ensureExists. When the language pack
          // is installed, we will be notified by an observer and automatically
          // call this.updateVoices(). See language_packs_connection.js for
          // more details.
          await this.languagePacksConnection_.ensureExists(locale);
          return;
        }

        // Add all voices for the language associated with |voice|.
        const voicesToLoad = [];
        for (let voice of this.voiceData_) {
          if (voice.language != command.data.language) {
            continue;
          }
          voicesToLoad.push(voice);
        }

        const keepAddingVoices = async () => {
          const voice = voicesToLoad.shift();
          if (!voice) {
            await this.updateVoices_();
            return;
          }

          // All voices have at least one speaker so we can take the first
          // speaker's name. Since all speaker names in a voice map to the same
          // voice, checking if one speaker exists, checks if all speakers
          // exist.
          let name = voice.speakers[0].name;
          const {voiceFileId, success} =
              await this.ensureExists(name, /* allowDownload = */ true);
          await keepAddingVoices();
        };
        await keepAddingVoices();
        break;
      case 'removeVoice':
        if (this.languagePacksConnection_ && Boolean(LanguagePacksConnection.localeToDlc(locale))) {
          // All we need to do is call uninstallPack. When the language pack
          // is uninstalled, we will be notified by an observer and
          // automatically call this.updateVoices(). See
          // language_packs_connection.js for more details.
          await this.languagePacksConnection_.uninstallPack(locale);
          return;
        }

        for (let voice of this.voiceData_) {
          if (voice.language != locale) {
            continue;
          }
          this.removeVoiceData_(voice['file_id']);
        }
        await this.updateVoices_();
        break;
    }
  }

  /**
   * @param {!Object} message
   * @private
   */
  sendToOptions_(message) {
    chrome.runtime.sendMessage(message, (response) => {
      if (chrome.runtime.lastError) {
        if (chrome.runtime.lastError.message ===
            'Could not establish connection. Receiving end does not exist.') {
          // Ignore kCouldNotEstablishConnection error since options page may
          // not be open.
          return;
        }

        // Re-throw other errors.
        throw chrome.runtime.lastError;
      }
    });
  }

  /**
   * @private
   */
  async updateVoices_() {
    if (!this.highQualityVoicesEnabled_) {
      this.voiceData_ = this.voiceData_.filter(voice => !voice.id.includes('-seanet'));
    }

    let data = this.voiceData_;
    let updateVoices = [];
    for (let i = 0; i < data.length; i++) {
      let voice = data[i];
      for (let j = 0; j < voice.speakers.length; j++) {
        let speaker = voice.speakers[j];
        this.voiceNameToId_[speaker.name] = voice.id;
        this.voiceNameToSpeakerName_[speaker.name] = speaker.speaker;
        this.speakerNameToGender_[speaker.speaker] = speaker.gender;

        const voiceFileId = voice['file_id'];
        this.voiceNameToFileId_[speaker.name] = voiceFileId;

        // Language is encoded into the id e.g. en-us-sfg. Take the first two
        // components.
        let parts = voice.id.split('-');
        if (parts.length < 2) {
          throw new Error(`Unexpected voice id format: ${voice.id}`);
        }

        let lang = parts[0] + '-' + parts[1].toUpperCase();

        // Add a few other attributes to the runtime voice data.
        voice.language = lang;
        voice.displayName = chrome.accessibilityPrivate.getDisplayNameForLocale(
                                voice.language, chrome.i18n.getUILanguage()) ||
            '';

        let languagePackInstalled = false;
        if (this.languagePacksConnection_ && Boolean(LanguagePacksConnection.localeToDlc(lang))) {
          languagePackInstalled = await this.languagePacksConnection_.isInstalled(lang);
        }
        voice.unloaded = !languagePackInstalled;

        // Skip this voice if it doesn't belong in the set seen by Chrome.
        if (voice.remote && voice.unloaded) {
          // A remote (http) url.
          this.voiceNameToUrl_[speaker.name] = voice.url;
          continue;
        }

        this.voiceNameToUrl_[speaker.name] = '/' + voice.id + '.zvoice';

        updateVoices.push({
          voiceName: speaker.name,
          lang: lang,
          eventTypes: ['start', 'end', 'error', 'word']
        });
      }
    }
    chrome.ttsEngine.updateVoices(updateVoices);
    this.sendToOptions_({type: 'updateVoices', data: this.voiceData_});
  }

  /**
   * Returns true if the voice matches our source of truth size and checksum.
   * @param {string} voiceFileId
   * @param {!Array<number>} buffer
   * @return {boolean}
   * @private
   */
  validateVoiceData_(voiceFileId, buffer) {
    // Compute the SHA256 hash and compare to our voices file.
    const sha256 = new SHA256();
    sha256.update(buffer);
    const hash = sha256.stringDigest();
    const voiceData = this.voiceData_.find(v => v['file_id'] == voiceFileId);
    return Boolean(voiceData && voiceData.sha256_checksum == hash &&
        voiceData.compressed_size == buffer.length);
  }

  /**
   * Returns the voice data from IndexedDB.
   * @param {string} voiceFileId
   * @return {!Promise<?Array<number>>}
   * @private
   */
  async getVoiceData_(voiceFileId) {
    if (!this.db_) {
      return null;
    }

    return new Promise(resolve => {
      const readRequest =
          this.db_.transaction('store').objectStore('store').get(voiceFileId);
      readRequest.onsuccess = () => {
        const result = readRequest.result;
        if (result && this.validateVoiceData_(voiceFileId, result)) {
          resolve(result);
        } else {
          this.removeVoiceData_(voiceFileId);
          resolve(null);
        }
      };

      readRequest.onerror = () => {
        resolve(null);
      };
    });
  }

  /**
   * Saves voice data to IndexedDB.
   * @private
   */
  saveVoiceData_(voiceFileId, buffer) {
    if (!this.db_) {
      return;
    }

    const writeTransaction = this.db_.transaction('store', 'readwrite');
    writeTransaction.objectStore('store').put(buffer, voiceFileId);
  }

  /**
   * Removes voice data from IndexedDB.
   */
  removeVoiceData_(voiceFileId) {
    if (!this.db_) {
      return;
    }

    const writeTransaction = this.db_.transaction('store', 'readwrite');
    writeTransaction.objectStore('store').delete(voiceFileId);

    // TODO: wire up to Chrome so that Chrome deletes the locally extracted
    // voices. They would be cleared on the next reboot, but the user may have
    // installed/uninstalled quite a number of voices prior to rebooting.
    delete this.installedVoices_[voiceFileId];
  }

  /**
   * Returns a locale, in <language>-<region> format, given a voice file ID.
   * @param {string} voiceFileId
   * @return {string}
   * @private
   */
   static getLocaleFromVoiceFileId_(voiceFileId) {
    // Voice file IDs follow the pattern: <locale>-x-multi-r<version>.
    return voiceFileId.toLowerCase().split('-x-')[0];
  }

  /**
   * Returns true if we should use language packs for the voice.
   * @param {string} voiceFileId
   * @return {boolean}
   * @private
   * @suppress {lintChecks} TODO(b/291134721): Unused - will remove once we revamp tests.
   */
  shouldUseLanguagePacksForVoice_(voiceFileId) {
    if (!this.languagePacksConnection_) {
      return false;
    }

    const locale = GoogleTtsEngine.getLocaleFromVoiceFileId_(voiceFileId);
    return Boolean(LanguagePacksConnection.localeToDlc(locale));
  }

  /**
   * Records a fetch success/failure metric for a particular source (XHR/DLC).
   * @param {number} value
   * @private
   */
  static recordGetVoiceBytesMetric_(value) {
    chrome.metricsPrivate.recordEnumerationValue(
      GET_VOICE_BYTES_METRIC_NAME,
      value,
      Object.keys(GET_VOICE_BYTES_METRIC_VALUES).length);
  }

  /**
   * Downloads voice files from language packs via DLC.
   * @param {string} voiceFileId
   * @return {!Promise<?Array<number>>} The voice file bytes.
   * @private
   */
  async getZippedVoiceFileBytesDlc_(voiceFileId) {
    return new Promise(async resolve => {
      const locale = GoogleTtsEngine.getLocaleFromVoiceFileId_(voiceFileId);

      // Ensure DLC exists on disk - install language pack if necessary.
      console.log(`Downloading language pack for locale: ${locale}`);
      await this.languagePacksConnection_.ensureExists(locale);
      const installed = await this.languagePacksConnection_.isInstalled(locale);
      if (!installed) {
        console.log(`Failed to ensure DLC exists for ${voiceFileId}`);
        resolve(null);
        return;
      }

      // Download using language packs.
      console.log(`${voiceFileId} doesn't exist, loading DLC.`);
      const dlc = LanguagePacksConnection.localeToDlc(locale);
      if (!dlc) {
        console.log(`Couldn't find DLC for voiceFileId: ${voiceFileId}`);
        GoogleTtsEngine.recordGetVoiceBytesMetric_(
            GET_VOICE_BYTES_METRIC_VALUES.DLC_NOT_FOUND);
        resolve(null);
        return;
      }

      let variant = chrome.accessibilityPrivate.TtsVariant.LITE;
      if (voiceFileId.includes('-seanet') && this.highQualityVoicesEnabled_) {
        variant = chrome.accessibilityPrivate.TtsVariant.STANDARD;
      }
      const contents = await new Promise(resolve =>
          chrome.accessibilityPrivate.getTtsDlcContents(/** @type {!chrome.accessibilityPrivate.DlcType} */ (dlc), variant, resolve));
      if (!contents) {
        GoogleTtsEngine.recordGetVoiceBytesMetric_(
            GET_VOICE_BYTES_METRIC_VALUES.DLC_NO_CONTENTS);
        resolve(null);
        return;
      }
      GoogleTtsEngine.recordGetVoiceBytesMetric_(
          GET_VOICE_BYTES_METRIC_VALUES.DLC_SUCCESS);
      resolve(new Uint8Array(contents));
    });
  }

/**
   * Downloads files from Google servers via fetch().
   * @param {string} voiceName
   * @return {!Promise<?Array<number>>} The voice file bytes.
   * @private
   */
async getZippedVoiceFileBytesFetch_(voiceName) {
  // Download from Google servers or locally from the extension directory.
  const voiceFileId = this.voiceNameToFileId_[voiceName];
  const url = this.voiceNameToUrl_[voiceName];
  console.log(`${voiceFileId} doesn't exist, loading from: ${url}`);
  try {
    const response = await fetch(url);
    if (!response.ok) {
      console.log(`Failed to fetch ${url}, status: ${response.status}`);
      GoogleTtsEngine.recordGetVoiceBytesMetric_(
        GET_VOICE_BYTES_METRIC_VALUES.XHR_NO_CONTENTS);
      return null;
    }
    const arrayBuffer = await response.arrayBuffer();
    if (arrayBuffer.byteLength === 0) {
      console.log(`Failed to fetch ${url}, no contents`);
      GoogleTtsEngine.recordGetVoiceBytesMetric_(
        GET_VOICE_BYTES_METRIC_VALUES.XHR_NO_CONTENTS);
      return null;
    }
    GoogleTtsEngine.recordGetVoiceBytesMetric_(
      GET_VOICE_BYTES_METRIC_VALUES.XHR_SUCCESS);
    return Array.from(new Uint8Array(arrayBuffer));
  } catch (error) {
    console.error(`Failed to fetch ${url} with error: ${error}`);
    GoogleTtsEngine.recordGetVoiceBytesMetric_(
      GET_VOICE_BYTES_METRIC_VALUES.XHR_NO_CONTENTS);
    return null;
  }
}

  /**
   * Downloads voice files from either Google servers via XmlHttpRequest or
   * language packs. First, try local extension directory, then language packs,
   * and if that fails, download from Google servers over XHR.
   * @param {string} voiceName
   * @return {!Promise<?Array<number>>} The voice file bytes.
   * @private
   */
  async getZippedVoiceFileBytes_(voiceName) {
    const voiceFileId = this.voiceNameToFileId_[voiceName];

    // Download locally-bundled voices (lives in extension directory).
    if (!this.isVoiceRemote_(voiceFileId)) {
      return this.getZippedVoiceFileBytesFetch_(voiceName);
    }

    // Try downloading voice using Language Packs DLCs.
    let bytes = await this.getZippedVoiceFileBytesDlc_(voiceFileId);
    if (!bytes) {
      // Language packs download failed, try downloading from Google servers.
      bytes = await this.getZippedVoiceFileBytesFetch_(voiceName);
    }
    return bytes;
  }
}

exports = {GoogleTtsEngine};

;return exports;});

